// Nepal Flood Map — Free RSS News Aggregator
// Generated by Hermes Agent (Nous Research)
// //
// Fetches from /api/rss-aggregate which aggregates:
// - NewsAPI.org (requires NEWS_API_KEY)
// - Google Custom Search (requires GOOGLE_API_KEY1-7 + GOOGLE_CX) — multi-key fallback
// - Free RSS feeds: ABC, NBC, CBS, The Watchers, EarthSky, Nepal News, OnlineKhabar
// ─────────────────────────────────────────────────────────────────────────────

"use client";

import { useEffect, useState } from "react";

interface NewsItem {
  title: string;
  link: string;
  pubDate: string;
  source: string;
  summary: string;
}

interface AggregateResponse {
  success: boolean;
  count: number;
  news: NewsItem[];
  last_updated: string;
  sources_used: {
    newsApi: boolean;
    google: boolean;
    rss: string[];
  };
  error?: string;
}

// Mock data for demo (used when API fails or during initial load)
