// ── Client-safe date formatter ─────────────────────────────────────────────────
// Returns "" during SSR and before client mount so server and client render match.
// After mount, fills in the formatted date.
function formattedDate(isoString: string): string {
  const [mounted, setMounted] = useState(false);
  useEffect(() => { setMounted(true); }, []);
  if (!mounted) return "";
  return new Date(isoString).toLocaleString();
}

export default function RSSNewsAggregator() {
  const [news, setNews] = useState<NewsItem[]>(MOCK_NEWS);
  const [loading, setLoading] = useState(false);
  const [lastFetch, setLastFetch] = useState<string>(new Date().toISOString());
  const [sources, setSources] = useState<AggregateResponse["sources_used"]>({
    newsApi: false,
    google: false,
    rss: [],
  });

  useEffect(() => {
    fetchNews();
  }, []);

  const fetchNews = async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/rss-aggregate");
      const data: AggregateResponse = await res.json();
      if (data.success && data.news.length > 0) {
        setNews(data.news);
        setSources(data.sources_used);
      }
      setLastFetch(data.last_updated);
    } catch {
      // Keep mock data on error
    } finally {
      setLoading(false);
    }
  };

  const refresh = () => {
    fetchNews();
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div className="text-xs text-gray-400 uppercase tracking-wide">
          Live News Feed
        </div>
        <button
          onClick={refresh}
          disabled={loading}
          className="text-[10px] text-blue-400 hover:text-blue-300 disabled:text-gray-500"
        >
          {loading ? "Refreshing..." : "Refresh"}
        </button>
      </div>

      <div className="text-[10px] text-gray-500">
        Sources: {sources.newsApi && "NewsAPI.org "}{sources.google && "Google News "}
        {sources.rss.length > 0 && `RSS: ${sources.rss.join(", ")}`}
      </div>

      <div className="space-y-2 max-h-96 overflow-y-auto pr-2">
        {news.map((item, i) => (
          <a
            key={i}
            href={item.link}
            target="_blank"
            rel="noreferrer"
            className="block bg-gray-800 rounded-lg p-3 hover:bg-gray-700 transition-colors"
          >
            <div className="flex items-start justify-between gap-2">
              <div className="text-sm text-white font-medium">{item.title}</div>
              <span className="text-[10px] text-gray-500 shrink-0">
                {item.source}
              </span>
            </div>
            <div className="text-[10px] text-gray-400 mt-1 line-clamp-2">
              {item.summary}
            </div>
            <div className="text-[10px] text-gray-600 mt-1">
              {formattedDate(item.pubDate)}
            </div>
          </a>
        ))}
      </div>

      <div className="text-[10px] text-gray-600 border-t border-gray-800 pt-2">
        Last fetched: {formattedDate(lastFetch)} ·{' '}
        {sources.newsApi || sources.google ? "Live APIs + " : ""}Free RSS feeds
      </div>
    </div>
  );
}
